\begin{aligned}
\ds{(g\circ f)}{\vec a}(\vec h,\vec k)
={}&\ds g{f(\vec a)}(\vec u,\vec v)\\
&+\df g{f(\vec a)}\bigl(\ds f{\vec a}(\vec h,\vec k)\bigr).
\end{aligned}

